<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{api}from'../api';import MemberManager from'./MemberManager.vue'
import {useTeacherWorkspace} from '../teacher-workspace'
const loading=ref(true),courses=ref<any[]>([]),terms=ref<any[]>([]),classes=ref<any[]>([]),institution=ref<any>({school_name:'',campuses:[],majors:[]})
const courseFilter=ref(''),termFilter=ref(''),search=ref(''),createOpen=ref(false),createType=ref<'course'|'term'|'class'>('class'),editingClassId=ref('')
const {restoreCourse}=useTeacherWorkspace(courses,courseFilter,true)
const courseForm=reactive({course_name:'',description:''})
const termForm=reactive({term_name:'',academic_year:'',teaching_period:''})
const classForm=reactive({course_id:'',term_id:'',class_name:'',class_variant:'',teaching_time_slot:'',campus:'',cohort_year:'',major:'',teaching_level:''}),memberManager=ref<any>(null)
const baseYear=new Date().getFullYear()
const academicYears=Array.from({length:9},(_,index)=>`${baseYear-index+2}-${baseYear-index+3}`)
const teachingPeriods=['第一学期','第二学期','春季学期','夏季学期','秋季学期','全年']
const cohortYears=Array.from({length:12},(_,index)=>String(baseYear-index+1))
const termNames=computed(()=>[...new Set([...terms.value.map(x=>x.term_name),...academicYears.flatMap(year=>teachingPeriods.map(period=>`${year} ${period}`))])])
function syncTermName(){if(termForm.academic_year&&termForm.teaching_period)termForm.term_name=`${termForm.academic_year} ${termForm.teaching_period}`}
const filteredClasses=computed(()=>classes.value.filter(row=>(!courseFilter.value||row.course_id===courseFilter.value)&&(!termFilter.value||row.term_id===termFilter.value)&&(!search.value||[row.course_name,row.class_name,row.class_variant,row.campus,row.major].join(' ').toLowerCase().includes(search.value.toLowerCase()))))
const studentCount=computed(()=>classes.value.reduce((sum,row)=>sum+Number(row.member_count||0),0))
async function load(){loading.value=true;try{const result=await Promise.all([api.get('/teacher/courses'),api.get('/teacher/terms'),api.get('/teacher/classes',{params:{_refresh:Date.now()},headers:{'Cache-Control':'no-cache'}}),api.get('/teacher/institution-profile')]);courses.value=result[0].data;terms.value=result[1].data;classes.value=result[2].data;institution.value=result[3].data}finally{loading.value=false}}
async function createCourse(){await api.post('/teacher/courses',courseForm);Object.assign(courseForm,{course_name:'',description:''});ElMessage.success('课程已创建');await load()}
async function createTerm(){await api.post('/teacher/terms',termForm);Object.assign(termForm,{term_name:'',academic_year:'',teaching_period:''});ElMessage.success('教学年度/时段已创建');await load()}
function resetClassForm(){Object.assign(classForm,{course_id:'',term_id:'',class_name:'',class_variant:'',teaching_time_slot:'',campus:'',cohort_year:'',major:'',teaching_level:''})} async function createClass(){await api.post('/teacher/classes',classForm);resetClassForm();ElMessage.success('教学班已创建');await load();await memberManager.value?.refresh()} function startEdit(row:any){editingClassId.value=row.class_id;Object.assign(classForm,{course_id:row.course_id,term_id:row.term_id,class_name:row.class_name,class_variant:row.class_variant||'',teaching_time_slot:row.teaching_time_slot||'',campus:row.campus||'',cohort_year:row.cohort_year||'',major:row.major||'',teaching_level:row.teaching_level||''});createType.value='class';createOpen.value=true} async function updateClass(){if(!editingClassId.value)return;await api.patch('/teacher/classes/'+editingClassId.value,classForm);resetClassForm();editingClassId.value='';ElMessage.success('教学班已更新');await load();await memberManager.value?.refresh()} async function removeClass(row:any){try{await ElMessageBox.confirm('删除“'+row.class_name+'”后，成员、课表和相关教学档案关联也会被删除，且无法恢复。是否继续？','删除教学班',{type:'warning',confirmButtonText:'确认删除',cancelButtonText:'取消'});await api.delete('/teacher/classes/'+row.class_id);if(editingClassId.value===row.class_id)closeCreate();ElMessage.success('教学班已删除');await load();await memberManager.value?.refresh()}catch(e:any){if(e==='cancel'||e==='close')return;ElMessage.error(e.response?.data?.detail||'删除失败')}} function closeCreate(){createOpen.value=false;editingClassId.value=''}
function startCreate(type:'course'|'term'|'class'){closeCreate();if(type==='class')resetClassForm();createType.value=type;createOpen.value=true}
async function create(){try{if(editingClassId.value){await updateClass()}else if(createType.value==='course'){await createCourse()}else if(createType.value==='term'){await createTerm()}else{await createClass()}createOpen.value=false}catch(e:any){ElMessage.error(e.response?.data?.detail||(editingClassId.value?'保存失败':'创建失败'))}}
onMounted(async()=>{await load();restoreCourse()})
</script>
<template><main class="content teaching-scope" v-loading="loading">
  <header class="workbench-hero"><div><h1>课程与教学班</h1><p>按课程、学年学期、校区和专业管理教学范围与学生账号。</p></div><div class="teaching-actions"><el-button class="teaching-create-action" @click="startCreate('course')">新增课程</el-button><el-button class="teaching-create-action" @click="startCreate('term')">新增学年学期</el-button><el-button class="teaching-create-action" @click="startCreate('class')">新增教学班</el-button></div></header>
  <section class="scope-metrics workbench-metrics"><article><span>共享课程</span><strong>{{courses.length}}</strong><small>教师维护的课程空间</small></article><article><span>学年学期</span><strong>{{terms.length}}</strong><small>可复用教学时段</small></article><article><span>教学班</span><strong>{{classes.length}}</strong><small>支持校区和自定义班型</small></article><article><span>班级成员人次</span><strong>{{studentCount}}</strong><small>同一学生跨班分别计数</small></article></section>
  <section class="scope-filter workbench-filters"><el-select v-model="courseFilter" clearable placeholder="全部课程"><el-option v-for="x in courses" :key="x.course_id" :label="x.course_name" :value="x.course_id"/></el-select><el-select v-model="termFilter" clearable placeholder="全部学年学期"><el-option v-for="x in terms" :key="x.term_id" :label="`${x.academic_year||''} ${x.teaching_period||x.term_name}`" :value="x.term_id"/></el-select><el-input v-model="search" clearable placeholder="搜索教学班、校区、专业或班型"/><el-button @click="courseFilter='';termFilter='';search=''">清空筛选</el-button></section>
  <section class="scope-layout"><aside class="workbench-panel"><div class="panel-title"><b>课程目录</b><small>{{courses.length}} 门课程</small></div><button type="button" class="course-card" :class="{active:!courseFilter}" @click="courseFilter=''">全部课程 <b>{{classes.length}}</b></button><button v-for="course in courses" :key="course.course_id" type="button" class="course-card" :class="{active:courseFilter===course.course_id}" @click="courseFilter=course.course_id"><span>{{course.course_name}}</span><b>{{course.class_count||0}}</b><small>{{course.description||'暂无课程说明'}}</small></button></aside>
    <section class="class-panel workbench-panel"><div class="panel-title"><div><b>教学班实施矩阵</b><small>同一课程可按校区、专业、年级和自定义版本并行开班</small></div><div class="panel-title-actions"><el-tag type="success">{{filteredClasses.length}} 个结果</el-tag><el-button size="small" :loading="loading" @click="load">刷新列表</el-button></div></div><el-table :data="filteredClasses" empty-text="当前筛选下没有教学班"><el-table-column prop="course_name" label="课程" min-width="150"/><el-table-column prop="term_name" label="学年学期" min-width="145"/><el-table-column label="教学班 / 版本" min-width="170"><template #default="s"><b>{{s.row.class_name}}</b><small class="cell-sub">{{s.row.class_variant||'通用班型'}}</small></template></el-table-column><el-table-column label="教学范围" min-width="210"><template #default="s"><span>{{[s.row.campus,s.row.cohort_year&&s.row.cohort_year+'级',s.row.major,s.row.teaching_level].filter(Boolean).join(' · ')||'未设置'}}</span><small class="cell-sub">{{s.row.teaching_time_slot||'未设置授课时间'}}</small></template></el-table-column><el-table-column label="学生" width="90"><template #default="s"><el-tag type="success">{{s.row.member_count||0}} 人</el-tag></template></el-table-column><el-table-column label="操作" width="150" fixed="right"><template #default="s"><el-button size="small" @click="startEdit(s.row)">编辑</el-button><el-button size="small" link type="danger" @click="removeClass(s.row)">删除</el-button></template></el-table-column></el-table></section>
  </section><MemberManager ref="memberManager"/>
  <el-dialog v-model="createOpen" :title="editingClassId?'编辑教学班':'创建教学范围'" width="min(720px,94vw)"><el-segmented v-if="!editingClassId" v-model="createType" :options="[{label:'课程',value:'course'},{label:'学年学期',value:'term'},{label:'教学班',value:'class'}]" block/><el-form v-if="createType==='course'" label-position="top" class="create-form"><el-form-item label="课程名称"><el-input v-model="courseForm.course_name"/></el-form-item><el-form-item label="课程说明"><el-input v-model="courseForm.description" type="textarea" :rows="4"/></el-form-item></el-form><el-form v-else-if="createType==='term'" label-position="top" class="create-form form-grid"><el-form-item label="显示名称"><el-select v-model="termForm.term_name" filterable allow-create default-first-option placeholder="选择或输入显示名称"><el-option v-for="name in termNames" :key="name" :label="name" :value="name"/></el-select></el-form-item><el-form-item label="学年"><el-select v-model="termForm.academic_year" filterable allow-create default-first-option placeholder="选择学年" @change="syncTermName"><el-option v-for="year in academicYears" :key="year" :label="year" :value="year"/></el-select></el-form-item><el-form-item label="教学时段"><el-select v-model="termForm.teaching_period" filterable allow-create default-first-option placeholder="选择教学时段" @change="syncTermName"><el-option v-for="period in teachingPeriods" :key="period" :label="period" :value="period"/></el-select></el-form-item></el-form><el-form v-else label-position="top" class="create-form form-grid"><el-alert class="school-match" type="success" :closable="false" :title="`已根据本系统所属学校匹配：${institution.school_name||'未配置学校'}`"/><el-form-item label="课程"><el-select v-model="classForm.course_id"><el-option v-for="x in courses" :key="x.course_id" :label="x.course_name" :value="x.course_id"/></el-select></el-form-item><el-form-item label="学年学期"><el-select v-model="classForm.term_id"><el-option v-for="x in terms" :key="x.term_id" :label="`${x.academic_year||''} ${x.teaching_period||x.term_name}`" :value="x.term_id"/></el-select></el-form-item><el-form-item label="教学班名称"><el-input v-model="classForm.class_name" placeholder="仁24信管1"/></el-form-item><el-form-item label="自定义班型 / 版本"><el-input v-model="classForm.class_variant" placeholder="A班 / 本部强化版"/></el-form-item><el-form-item label="校区"><el-select v-model="classForm.campus" filterable allow-create default-first-option placeholder="选择校区"><el-option v-for="value in institution.campuses" :key="value" :label="value" :value="value"/></el-select></el-form-item><el-form-item label="入学年级"><el-select v-model="classForm.cohort_year" filterable placeholder="选择入学年级"><el-option v-for="year in cohortYears" :key="year" :label="year+'级'" :value="year"/></el-select></el-form-item><el-form-item label="专业"><el-select v-model="classForm.major" filterable allow-create default-first-option placeholder="搜索或选择专业"><el-option v-for="value in institution.majors" :key="value" :label="value" :value="value"/></el-select></el-form-item><el-form-item label="教学层级"><el-input v-model="classForm.teaching_level" placeholder="可选，不限于难度"/></el-form-item><el-form-item label="具体授课时间"><el-input v-model="classForm.teaching_time_slot" placeholder="周一 1-2 节 / 第1-8周"/></el-form-item></el-form><template #footer><el-button @click="closeCreate">取消</el-button><el-button type="primary" @click="create">{{editingClassId?'保存修改':'确认创建'}}</el-button></template></el-dialog>
</main></template>
<style scoped>.school-match{grid-column:1/-1;margin-bottom:14px}.teaching-actions{display:flex;align-items:center;justify-content:flex-end;gap:10px;flex-wrap:wrap}.teaching-actions :deep(.el-button+.el-button){margin-left:0}.teaching-actions :deep(.teaching-create-action){--el-button-text-color:#000;--el-button-hover-text-color:#000;--el-button-active-text-color:#000;--el-button-disabled-text-color:#000;display:inline-flex;min-width:140px;min-height:36px;height:auto;box-sizing:border-box;align-items:center;justify-content:center;margin:0!important;padding:8px 15px;overflow:hidden;white-space:nowrap;color:#000!important;background:#fff!important;border-color:#d7dcda!important;font-size:14px;line-height:1.5;vertical-align:middle}.teaching-actions :deep(.teaching-create-action span){color:#000!important;font-size:14px;line-height:1.5}.teaching-actions :deep(.teaching-create-action:hover),.teaching-actions :deep(.teaching-create-action:focus),.teaching-actions :deep(.teaching-create-action:active){color:#000!important;background:#f5f6f5!important;border-color:#b8bfbc!important}@media(max-width:700px){.teaching-actions{justify-content:flex-start}}</style>
<style scoped>.teaching-scope{display:grid;gap:17px;min-height:100vh;background:#f3f7f7}.scope-metrics{margin:0}.scope-filter{grid-template-columns:minmax(220px,1fr) minmax(220px,1fr) minmax(300px,1.4fr) auto}.scope-layout{display:grid;grid-template-columns:270px minmax(0,1fr);gap:15px;align-items:start}.scope-layout>aside,.class-panel{padding:18px}.panel-title{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:15px}.panel-title>div{display:grid;gap:4px}.panel-title-actions{display:flex!important;align-items:center;gap:8px;flex-shrink:0}.panel-title small{color:#788a85}.course-card{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:5px 10px;width:100%;margin-bottom:8px;padding:13px;border:1px solid #dfe9e6;border-radius:11px;background:#fff;color:#31554f;text-align:left;cursor:pointer}.course-card:hover,.course-card.active{border-color:#79aaa4;background:#edf7f4;box-shadow:inset 3px 0 #23746f}.course-card span{font-weight:700}.course-card small{grid-column:1/-1;color:#81918d;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.cell-sub{display:block;margin-top:4px;color:#7c8d88}.create-form{margin-top:22px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 15px}@media(max-width:900px){.scope-filter,.scope-layout{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr}}@media(max-width:600px){.panel-title{align-items:flex-start;flex-direction:column}.panel-title-actions{width:100%;justify-content:space-between}}</style>
